import { Button, Heading, Input, Toolbar } from '@advui/core'
import { PlusIcon } from '@advui/icons'

export default function ToolbarRegions() {
  return (
    <Toolbar
      aria-label="Users"
      variant="outline"
      width="100%"
      leading={
        <Heading level={3} size="lg">
          Users
        </Heading>
      }
      // The field fills the center, up to a width.
      center={
        <Input
          size="sm"
          flex={1}
          maxWidth="96"
          placeholder="Search users…"
          aria-label="Search users"
        />
      }
      trailing={
        <Button size="sm" icon={<PlusIcon />}>
          Add user
        </Button>
      }
    />
  )
}

import { Button, Text, Toolbar, VStack } from '@advui/core'

const variants = ['default', 'outline', 'filled', 'ghost'] as const

export default function ToolbarVariants() {
  return (
    <VStack gap="3" width="100%">
      {variants.map((variant) => (
        <Toolbar
          key={variant}
          aria-label={`${variant} toolbar`}
          variant={variant}
          leading={
            <Text size="sm" tone="muted">
              {variant}
            </Text>
          }
          trailing={
            <>
              <Button size="sm" variant="outline">
                Cancel
              </Button>
              <Button size="sm">Save</Button>
            </>
          }
        />
      ))}
    </VStack>
  )
}

import { Button, Toolbar, VStack } from '@advui/core'
import { DownloadIcon, RotateCwIcon } from '@advui/icons'

const sizes = ['sm', 'md', 'lg'] as const

// The toolbar's size sets its gap, padding and height. Controls keep their
// own size, so give them the same one.
export default function ToolbarSizes() {
  return (
    <VStack gap="3" align="start">
      {sizes.map((size) => (
        <Toolbar key={size} aria-label={`${size} toolbar`} size={size} variant="outline">
          <Button size={size} variant="ghost" icon={<RotateCwIcon />}>
            Refresh
          </Button>
          <Button size={size} variant="ghost" icon={<DownloadIcon />}>
            Export
          </Button>
        </Toolbar>
      ))}
    </VStack>
  )
}

import { Box, Button, Heading, Input, Toolbar } from '@advui/core'
import { FilterIcon, PlusIcon } from '@advui/icons'

// A phone-width frame. With `wrap`, the field and the actions move onto new
// lines instead of squeezing the title; the actions stay at the end edge.
export default function ToolbarWrap() {
  return (
    <Box
      width="100%"
      maxWidth="80"
      borderWidth={1}
      borderColor="border"
      borderStyle="dashed"
      borderRadius="lg"
    >
      <Toolbar
        aria-label="Orders"
        wrap
        leading={
          <Heading level={3} size="lg">
            Orders
          </Heading>
        }
        center={
          <Input
            size="sm"
            flex={1}
            minWidth="40"
            placeholder="Search orders…"
            aria-label="Search orders"
          />
        }
        trailing={
          <>
            <Button size="sm" variant="outline" icon={<FilterIcon />}>
              Filter
            </Button>
            <Button size="sm" icon={<PlusIcon />}>
              New order
            </Button>
          </>
        }
      />
    </Box>
  )
}
